lake_ice_carving_station.source:
export const envelope = [17, 14, 17];

export default function build(api) {
  const { theme } = api;
  const wood = theme.wood;
  const stone = theme.stone;
  const roof = theme.roof;

  const seatY = 4;

  // Safe setter within envelope
  function set(x, y, z, block) {
    if (x >= 0 && x < 17 && y >= 0 && y < 14 && z >= 0 && z < 17) {
      api.set(x, y, z, block);
    }
  }

  // Block state helpers
  function idOf(b) {
    return b.split("[")[0];
  }

  function stair(base, facing, half = "bottom", shape = "straight") {
    return `${idOf(base)}[facing=${facing},half=${half},shape=${shape}]`;
  }

  function slab(base, type = "bottom") {
    return `${idOf(base)}[type=${type}]`;
  }

  function trapdoor(base, facing, half = "bottom", open = false) {
    return `${idOf(base)}[facing=${facing},half=${half},open=${open}]`;
  }

  function log(base, axis = "y") {
    return `${idOf(base)}[axis=${axis}]`;
  }

  function fence(base) {
    return idOf(base);
  }

  function wall(base) {
    return idOf(base);
  }

  function door(base, facing, half = "lower", hinge = "left", open = false) {
    return `${idOf(base)}[facing=${facing},half=${half},hinge=${hinge},open=${open}]`;
  }

  // -------------------------------------------------------------
  // 1. FOUNDATIONS & TERRAIN CONFORMITY (Rule 5 & 6)
  // -------------------------------------------------------------
  // Pilings grid and platform supports
  const pilings = [
    [2, 2], [6, 2], [10, 2], [14, 2],
    [2, 6], [6, 6], [10, 6], [14, 6],
    [2, 10], [6, 10], [10, 10], [14, 10],
    [2, 14], [6, 14], [10, 14], [14, 14],
    [4, 2], [12, 2], [2, 4], [14, 4],
    [2, 12], [14, 12], [6, 4], [10, 4]
  ];

  const pilingSet = new Set(pilings.map(([px, pz]) => `${px},${pz}`));

  // Ground-to-deck pillars
  for (let x = 2; x <= 15; x++) {
    for (let z = 2; z <= 15; z++) {
      const h = api.heightAt(x, z);
      const groundY = Math.max(0, Math.min(seatY + h, 5));
      const isPiling = pilingSet.has(`${x},${z}`);
      const isBorder = (x === 2 || x === 15 || z === 2 || z === 15);

      if (isPiling || isBorder) {
        for (let y = groundY; y <= 4; y++) {
          if (y <= 1) {
            set(x, y, z, stone.primary);
          } else {
            set(x, y, z, log(wood.log, "y"));
          }
        }
      } else {
        // Under-deck subfloor grid
        for (let y = groundY; y <= 4; y++) {
          if (y === 4) {
            set(x, y, z, log(wood.stripped, (x % 2 === 0 ? "x" : "z")));
          } else if (y >= 2) {
            set(x, y, z, wood.planks);
          } else {
            set(x, y, z, stone.primary);
          }
        }
      }
    }
  }

  // Cross-bracing between perimeter pilings under dock
  for (let x = 3; x <= 13; x += 4) {
    set(x, 3, 2, fence(wood.fence));
    set(x + 1, 3, 2, fence(wood.fence));
    set(x, 3, 14, fence(wood.fence));
    set(x + 1, 3, 14, fence(wood.fence));
  }
  for (let z = 3; z <= 13; z += 4) {
    set(2, 3, z, fence(wood.fence));
    set(2, 3, z + 1, fence(wood.fence));
    set(15, 3, z, fence(wood.fence));
    set(15, 3, z + 1, fence(wood.fence));
  }

  // -------------------------------------------------------------
  // 2. MAIN TIMBER STAGING DOCK (y = 5)
  // -------------------------------------------------------------
  for (let x = 2; x <= 15; x++) {
    for (let z = 2; z <= 15; z++) {
      // Leave opening for the ice chute slipway at front
      if (x >= 7 && x <= 9 && z >= 2 && z <= 4) {
        continue;
      }
      // Cabin floor interior is at y=4, deck at y=5
      if (x >= 10 && x <= 14 && z >= 10 && z <= 14) {
        set(x, 4, z, wood.planks);
        continue;
      }

      // Dock planking with textured timber wear
      if ((x + z) % 7 === 0) {
        set(x, 5, z, log(wood.stripped, "z"));
      } else if ((x * 3 + z) % 11 === 0) {
        set(x, 5, z, slab(wood.slab, "top"));
      } else {
        set(x, 5, z, wood.planks);
      }
    }
  }

  // Edge log framing
  for (let x = 2; x <= 15; x++) {
    if (x < 7 || x > 9) set(x, 5, 2, log(wood.log, "x"));
    set(x, 5, 15, log(wood.log, "x"));
  }
  for (let z = 2; z <= 15; z++) {
    set(2, 5, z, log(wood.log, "z"));
    set(15, 5, z, log(wood.log, "z"));
  }

  // -------------------------------------------------------------
  // 3. ICE HARVEST SLIPWAY & CUTTING CHUTE (North, z = 0..4)
  // -------------------------------------------------------------
  // Sloped ramp descending to lake ice
  for (let x = 6; x <= 10; x++) {
    const isChuteCenter = (x >= 7 && x <= 9);

    // Lake edge apron at z = 0
    const h0 = Math.max(0, Math.min(seatY + api.heightAt(x, 0), 3));
    for (let y = h0; y <= 3; y++) {
      set(x, y, 0, isChuteCenter ? "minecraft:packed_ice" : log(wood.log, "z"));
    }

    // z = 1
    const h1 = Math.max(0, Math.min(seatY + api.heightAt(x, 1), 3));
    for (let y = h1; y <= 3; y++) {
      set(x, y, 1, isChuteCenter ? "minecraft:packed_ice" : log(wood.log, "z"));
    }
    if (!isChuteCenter) {
      set(x, 4, 1, x === 6 ? stair(wood.stairs, "east") : stair(wood.stairs, "west"));
    }

    // z = 2
    const h2 = Math.max(0, Math.min(seatY + api.heightAt(x, 2), 3));
    for (let y = h2; y <= 3; y++) {
      set(x, y, 2, isChuteCenter ? "minecraft:packed_ice" : log(wood.log, "y"));
    }
    if (isChuteCenter) {
      set(x, 4, 2, stair(wood.stairs, "north"));
    } else {
      set(x, 4, 2, log(wood.log, "z"));
      set(x, 5, 2, log(wood.log, "y"));
    }

    // z = 3
    for (let y = 3; y <= 4; y++) {
      set(x, y, 3, isChuteCenter ? "minecraft:packed_ice" : log(wood.log, "z"));
    }
    if (!isChuteCenter) {
      set(x, 5, 3, fence(wood.fence));
    }

    // z = 4
    set(x, 4, 4, log(wood.log, "x"));
    if (isChuteCenter) {
      set(x, 5, 4, "minecraft:packed_ice");
    }
  }

  // Harvested ice blocks in chute
  set(8, 4, 1, "minecraft:blue_ice");

  // -------------------------------------------------------------
  // 4. HEAVY LOG HOIST CRANE & GANTRY (x = 6..10, z = 1..5)
  // -------------------------------------------------------------
  // A-Frame vertical masts
  for (let y = 5; y <= 11; y++) {
    set(6, y, 4, log(wood.log, "y"));
    set(10, y, 4, log(wood.log, "y"));
  }

  // Mast side struts and braces
  set(5, 6, 4, stair(wood.stairs, "east"));
  set(11, 6, 4, stair(wood.stairs, "west"));
  set(6, 6, 3, stair(wood.stairs, "south"));
  set(10, 6, 3, stair(wood.stairs, "south"));
  for (let y = 6; y <= 10; y++) {
    set(6, y, 5, fence(wood.fence));
    set(10, y, 5, fence(wood.fence));
  }

  // Gantry crossbeam at y = 11
  for (let x = 5; x <= 11; x++) {
    set(x, 11, 4, log(wood.log, "x"));
  }
  set(5, 11, 4, trapdoor(wood.trapdoor, "west", "top"));
  set(11, 11, 4, trapdoor(wood.trapdoor, "east", "top"));

  // Forward boom / jib extending north over ice chute (x = 8, z = 1..4)
  for (let z = 1; z <= 4; z++) {
    set(8, 11, z, log(wood.log, "z"));
  }
  set(8, 12, 3, stair(wood.stairs, "south"));
  set(8, 12, 2, slab(wood.slab, "bottom"));
  set(7, 11, 3, stair(wood.stairs, "east", "top"));
  set(9, 11, 3, stair(wood.stairs, "west", "top"));

  // Winch drum mechanism
  set(8, 6, 4, log(wood.stripped, "x"));
  set(7, 6, 4, "minecraft:grindstone[face=wall,facing=west]");
  set(9, 6, 4, trapdoor(wood.trapdoor, "east", "top"));
  for (let y = 7; y <= 10; y++) {
    set(8, y, 4, "minecraft:chain[axis=y]");
  }

  // Hanging hoist chains and suspended blue ice block
  for (let y = 7; y <= 10; y++) {
    set(8, y, 2, "minecraft:chain[axis=y]");
  }
  set(8, 6, 2, "minecraft:iron_bars");
  set(8, 5, 2, "minecraft:blue_ice");
  set(8, 10, 1, "minecraft:lantern[hanging=true]");

  // -------------------------------------------------------------
  // 5. ICE CARVING & SAWING BENCH (West staging area)
  // -------------------------------------------------------------
  // Stacks of harvested ice blocks
  set(3, 6, 3, "minecraft:packed_ice");
  set(4, 6, 3, "minecraft:blue_ice");
  set(3, 6, 4, "minecraft:blue_ice");
  set(4, 6, 4, "minecraft:packed_ice");
  set(3, 7, 3, "minecraft:blue_ice");
  set(4, 7, 4, "minecraft:packed_ice");
  set(3, 8, 3, "minecraft:snow[layers=1]");
  set(4, 8, 4, "minecraft:snow[layers=1]");

  // Cutting sawhorse & grindstone
  set(3, 6, 5, "minecraft:grindstone[face=floor,facing=north]");
  set(4, 6, 5, log(wood.stripped, "x"));
  set(4, 7, 5, "minecraft:iron_bars");
  set(5, 6, 5, stair(wood.stairs, "west"));

  // -------------------------------------------------------------
  // 6. FISH-WEIGHING CANOPY & BALANCE SCALE (West, x = 2..8, z = 8..15)
  // -------------------------------------------------------------
  // Heavy timber posts
  const canopyPosts = [[2, 8], [8, 8], [2, 15], [8, 15]];
  for (const [cx, cz] of canopyPosts) {
    for (let y = 5; y <= 9; y++) {
      set(cx, y, cz, log(wood.log, "y"));
    }
  }

  // Top rafter beams at y = 9
  for (let x = 2; x <= 8; x++) {
    set(x, 9, 8, log(wood.log, "x"));
    set(x, 9, 15, log(wood.log, "x"));
  }
  for (let z = 8; z <= 15; z++) {
    set(2, 9, z, log(wood.log, "z"));
    set(8, 9, z, log(wood.log, "z"));
  }

  // Lean-to roof over weighing station
  for (let z = 7; z <= 16; z++) {
    set(1, 9, z, slab(roof.slab, "top"));
    set(2, 9, z, slab(roof.slab, "top"));
    set(3, 10, z, slab(roof.slab, "bottom"));
    set(4, 10, z, slab(roof.slab, "bottom"));
    set(5, 10, z, slab(roof.slab, "top"));
    set(6, 10, z, slab(roof.slab, "top"));
    set(7, 11, z, slab(roof.slab, "bottom"));
    set(8, 11, z, slab(roof.slab, "bottom"));

    // Taiga snow on canopy
    set(1, 10, z, "minecraft:snow[layers=1]");
    set(3, 11, z, "minecraft:snow[layers=1]");
    set(5, 11, z, "minecraft:snow[layers=1]");
    set(7, 12, z, "minecraft:snow[layers=1]");
  }

  // Steelyard Balance Weighing Scale
  set(5, 6, 11, log(wood.log, "y"));
  set(5, 7, 11, log(wood.log, "y"));
  set(5, 8, 11, wall(stone.wall));

  // Balance beam
  set(4, 8, 11, "minecraft:iron_bars");
  set(5, 9, 11, log(wood.stripped, "x"));
  set(6, 8, 11, "minecraft:iron_bars");

  // West pan (Counterweight)
  set(3, 8, 11, "minecraft:chain[axis=y]");
  set(3, 7, 11, "minecraft:chain[axis=y]");
  set(3, 6, 11, "minecraft:anvil[facing=north]");

  // East pan (Salted fish catch basket)
  set(7, 8, 11, "minecraft:chain[axis=y]");
  set(7, 7, 11, "minecraft:chain[axis=y]");
  set(7, 6, 11, "minecraft:barrel[facing=up]");

  // Fish curing barrels & salting tubs
  set(3, 6, 13, "minecraft:barrel[facing=up]");
  set(4, 6, 13, "minecraft:barrel[facing=north]");
  set(3, 6, 14, "minecraft:barrel[facing=east]");
  set(4, 6, 14, "minecraft:barrel[facing=up]");
  set(3, 7, 13, "minecraft:barrel[facing=up]");
  set(4, 7, 14, slab(wood.slab, "bottom"));

  set(3, 6, 9, "minecraft:cauldron");

  // Fish drying rack
  set(6, 6, 14, fence(wood.fence));
  set(6, 7, 14, fence(wood.fence));
  set(6, 8, 14, log(wood.log, "x"));
  set(6, 7, 13, "minecraft:lantern[hanging=true]");

  // Central warming brazier / hearth
  set(8, 5, 7, stone.primary);
  set(8, 6, 7, "minecraft:campfire[lit=true,facing=north]");
  set(7, 6, 7, stair(stone.stairs, "east"));
  set(9, 6, 7, stair(stone.stairs, "west"));
  set(8, 6, 6, stair(stone.stairs, "south"));

  // -------------------------------------------------------------
  // 7. WEIGH-MASTER OFFICE & HARBOR SHACK (Southeast, x = 9..15, z = 9..15)
  // -------------------------------------------------------------
  // Corner posts
  const cabinPosts = [[9, 9], [15, 9], [9, 15], [15, 15]];
  for (const [cx, cz] of cabinPosts) {
    for (let y = 5; y <= 8; y++) {
      set(cx, y, cz, log(wood.log, "y"));
    }
  }

  // Walls
  // North wall (z = 9)
  for (let x = 10; x <= 14; x++) {
    set(x, 5, 9, wood.planks);
    set(x, 8, 9, wood.planks);
  }
  set(10, 6, 9, wood.planks);
  set(10, 7, 9, wood.planks);
  set(11, 6, 9, wood.planks);
  set(11, 7, 9, fence(wood.fence)); // window
  // Doorway at x = 12
  set(12, 5, 9, wood.planks);
  set(12, 6, 9, door(wood.door, "north", "lower"));
  set(12, 7, 9, door(wood.door, "north", "upper"));
  set(13, 6, 9, wood.planks);
  set(13, 7, 9, fence(wood.fence)); // window
  set(14, 6, 9, wood.planks);
  set(14, 7, 9, wood.planks);

  // South wall (z = 15)
  for (let x = 10; x <= 14; x++) {
    for (let y = 5; y <= 8; y++) {
      if (x === 12 && y === 7) {
        set(x, y, 15, fence(wood.fence)); // window
      } else {
        set(x, y, 15, wood.planks);
      }
    }
  }

  // West wall (x = 9)
  for (let z = 10; z <= 14; z++) {
    for (let y = 5; y <= 8; y++) {
      if (z === 12 && y === 7) {
        set(9, y, z, fence(wood.fence)); // window
      } else {
        set(9, y, z, wood.planks);
      }
    }
  }

  // East wall (x = 15)
  for (let z = 10; z <= 14; z++) {
    for (let y = 5; y <= 8; y++) {
      if (z === 12 && y === 7) {
        set(15, y, z, fence(wood.fence)); // window
      } else {
        set(15, y, z, wood.planks);
      }
    }
  }

  // Gable Roof over Cabin (Ridge at x = 12, running z = 8..16)
  for (let z = 8; z <= 16; z++) {
    // West slope
    set(8, 8, z, stair(roof.stairs, "east"));
    set(8, 7, z, stair(wood.stairs, "west", "top"));
    set(9, 9, z, stair(roof.stairs, "east"));
    set(9, 8, z, stair(wood.stairs, "west", "top"));
    set(10, 10, z, stair(roof.stairs, "east"));
    set(10, 9, z, stair(wood.stairs, "west", "top"));
    set(11, 11, z, stair(roof.stairs, "east"));
    set(11, 10, z, stair(wood.stairs, "west", "top"));

    // Ridge peak
    set(12, 12, z, slab(roof.slab, "bottom"));
    set(12, 11, z, wood.planks);

    // East slope
    set(13, 11, z, stair(roof.stairs, "west"));
    set(13, 10, z, stair(wood.stairs, "east", "top"));
    set(14, 10, z, stair(roof.stairs, "west"));
    set(14, 9, z, stair(wood.stairs, "east", "top"));
    set(15, 9, z, stair(roof.stairs, "west"));
    set(15, 8, z, stair(wood.stairs, "east", "top"));
    set(16, 8, z, stair(roof.stairs, "west"));
    set(16, 7, z, stair(wood.stairs, "east", "top"));

    // Taiga snow cover on roof
    set(8, 9, z, "minecraft:snow[layers=1]");
    set(9, 10, z, "minecraft:snow[layers=1]");
    set(10, 11, z, "minecraft:snow[layers=1]");
    set(11, 12, z, "minecraft:snow[layers=1]");
    set(12, 13, z, "minecraft:snow[layers=1]");
    set(13, 12, z, "minecraft:snow[layers=1]");
    set(14, 11, z, "minecraft:snow[layers=1]");
    set(15, 10, z, "minecraft:snow[layers=1]");
    set(16, 9, z, "minecraft:snow[layers=1]");
  }

  // Gable end pediments
  const gableZ = [9, 15];
  for (const gz of gableZ) {
    set(10, 9, gz, wood.planks);
    set(14, 9, gz, wood.planks);
    set(11, 9, gz, wood.planks);
    set(11, 10, gz, wood.planks);
    set(13, 9, gz, wood.planks);
    set(13, 10, gz, wood.planks);
    set(12, 9, gz, wood.planks);
    set(12, 10, gz, fence(wood.fence)); // attic vent
    set(12, 11, gz, wood.planks);
  }

  // Stone chimney on cabin
  set(14, 9, 13, stone.primary);
  set(14, 10, 13, stone.primary);
  set(14, 11, 13, stone.primary);
  set(14, 12, 13, wall(stone.wall));
  set(14, 13, 13, "minecraft:campfire[lit=true]");

  // Porch light over cabin door
  set(12, 8, 8, fence(wood.fence));
  set(12, 7, 8, "minecraft:lantern[hanging=true]");

  // -------------------------------------------------------------
  // 8. STAGED HAULING SLEDS & EQUIPMENT
  // -------------------------------------------------------------
  // Sled 1 (East staging lane, x = 13..14, z = 3..6)
  set(13, 6, 3, fence(wood.fence)); // hitch
  set(13, 6, 4, stair(wood.stairs, "north"));
  set(14, 6, 4, stair(wood.stairs, "north"));
  set(13, 6, 5, "minecraft:chest[facing=west]");
  set(14, 6, 5, "minecraft:barrel[facing=up]");
  set(13, 6, 6, stair(wood.stairs, "south"));
  set(14, 6, 6, stair(wood.stairs, "south"));
  set(14, 7, 5, trapdoor(wood.trapdoor, "east", "bottom"));

  // Sled 2 (West staging lane loaded with blue ice)
  set(3, 6, 7, stair(wood.stairs, "north"));
  set(4, 6, 7, stair(wood.stairs, "north"));
  set(3, 6, 8, "minecraft:blue_ice");
  set(4, 6, 8, slab(wood.slab, "bottom"));
  set(3, 6, 9, stair(wood.stairs, "south"));
  set(4, 6, 9, stair(wood.stairs, "south"));

  // -------------------------------------------------------------
  // 9. DOCK RAILINGS, LANTERNS & SNOW DUSTING
  // -------------------------------------------------------------
  // Perimeter fence railings
  // West edge
  for (let z = 2; z <= 15; z++) {
    if (z === 2 || z === 6 || z === 10 || z === 15) {
      set(2, 6, z, log(wood.log, "y"));
    } else {
      set(2, 6, z, fence(wood.fence));
    }
  }

  // North edge
  for (let x = 2; x <= 5; x++) {
    if (x === 2) {
      set(x, 6, 2, log(wood.log, "y"));
    } else {
      set(x, 6, 2, fence(wood.fence));
    }
  }
  for (let x = 11; x <= 15; x++) {
    if (x === 15) {
      set(x, 6, 2, log(wood.log, "y"));
    } else {
      set(x, 6, 2, fence(wood.fence));
    }
  }

  // East edge
  for (let z = 2; z <= 8; z++) {
    if (z === 2 || z === 6) {
      set(15, 6, z, log(wood.log, "y"));
    } else {
      set(15, 6, z, fence(wood.fence));
    }
  }

  // Corner lanterns
  set(2, 7, 2, "minecraft:lantern[hanging=false]");
  set(15, 7, 2, "minecraft:lantern[hanging=false]");
  set(6, 7, 4, "minecraft:lantern[hanging=false]");

  // Snow dusting on exposed dock planks
  for (let x = 2; x <= 15; x++) {
    for (let z = 2; z <= 15; z++) {
      if (api.random() < 0.22) {
        if (x >= 10 && x <= 14 && z >= 10 && z <= 14) continue; // inside cabin
        if (x >= 7 && x <= 9 && z >= 2 && z <= 4) continue; // chute
        set(x, 6, z, "minecraft:snow[layers=1]");
      }
    }
  }

  return {
    name: "lake_ice_carving_station",
    seatY,
    anchors: {
      front: [8, 4, 0],
      door: [12, 5, 9],
      chute: [8, 4, 1],
      scale: [5, 6, 11]
    },
    interiors: [
      {
        min: [10, 5, 10],
        max: [14, 7, 14],
        kind: "quarters"
      }
    ]
  };
}

ice_fishing_shanty.source:
export const envelope = [9, 11, 9];

export default function build(api) {
  const size = api.size;
  const inst = api.instance.index;
  const rng = () => api.random();

  // 1. Theme extraction with robust fallbacks
  const pWood = api.theme.wood || {};
  const pStone = api.theme.stone || {};
  const pRoof = api.theme.roof || {};
  const pGround = api.theme.ground || {};

  const woodPlanks = pWood.planks || "minecraft:spruce_planks";
  const woodLog = pWood.log || "minecraft:spruce_log";
  const woodStripped = pWood.stripped || "minecraft:stripped_spruce_log";
  const woodStairs = pWood.stairs || "minecraft:spruce_stairs";
  const woodSlab = pWood.slab || "minecraft:spruce_slab";
  const woodFence = pWood.fence || "minecraft:spruce_fence";
  const woodDoor = pWood.door || "minecraft:spruce_door";
  const woodTrapdoor = pWood.trapdoor || "minecraft:spruce_trapdoor";

  const stonePrimary = pStone.primary || "minecraft:cobblestone";
  const stoneAccent = pStone.accent || "minecraft:stone_bricks";
  const stoneWall = pStone.wall || "minecraft:cobblestone_wall";
  const stoneSlab = pStone.slab || "minecraft:cobblestone_slab";

  const roofStairs = pRoof.stairs || woodStairs;
  const roofSlab = pRoof.slab || woodSlab;
  const roofSolid = pRoof.solid || woodPlanks;

  const groundPlinth = pGround.plinth || stonePrimary;

  function withState(baseBlock, stateStr) {
    const base = baseBlock.split("[")[0];
    return stateStr ? `${base}[${stateStr}]` : base;
  }

  // Grid buffer to manage writes, enforce bounds, and ensure 6-connectivity
  const grid = new Map();

  function set(x, y, z, block) {
    if (x < 0 || x >= size[0] || y < 0 || y >= size[1] || z < 0 || z >= size[2]) return;
    grid.set(`${x},${y},${z}`, block);
  }

  function get(x, y, z) {
    return grid.get(`${x},${y},${z}`);
  }

  const seatY = 2;
  function getGroundY(x, z) {
    return seatY + api.heightAt(x, z);
  }

  function fillPillarDown(x, z, fromY, blockStr) {
    const gY = Math.max(0, Math.min(fromY, getGroundY(x, z)));
    for (let y = fromY; y >= gY; y--) {
      set(x, y, z, blockStr);
    }
  }

  // 2. Instance variations
  const isWide = (inst % 3 === 1);
  const x0 = isWide ? 1 : 2;
  const x1 = 6;
  const z0 = 2;
  const z1 = 6;
  const xMid = Math.floor((x0 + x1) / 2);

  const doorX = (inst % 2 === 0) ? (x0 + 2) : (x0 + 1);
  const sledSide = (x0 === 2) ? "west" : "east";
  const sledX = (sledSide === "west") ? 0 : 7;
  const rackX = (sledSide === "west") ? 7 : 0;

  const stoveInRight = (inst % 2 === 0);
  const stoveX = stoveInRight ? (x1 - 1) : (x0 + 1);
  const stoveZ = z1 - 1;

  // 3. Foundation and Heavy Skid Runners (y = 2)
  const runnerLX = x0;
  const runnerRX = x1;

  // Timber skids along Z
  for (let z = 1; z <= 7; z++) {
    set(runnerLX, 2, z, withState(woodLog, "axis=z"));
    set(runnerRX, 2, z, withState(woodLog, "axis=z"));
    fillPillarDown(runnerLX, z, 1, groundPlinth);
    fillPillarDown(runnerRX, z, 1, groundPlinth);
  }

  // Upturned skid runner noses (North) and tails (South)
  set(runnerLX, 2, 0, withState(woodStairs, "facing=south,half=bottom"));
  set(runnerRX, 2, 0, withState(woodStairs, "facing=south,half=bottom"));
  fillPillarDown(runnerLX, 0, 1, groundPlinth);
  fillPillarDown(runnerRX, 0, 1, groundPlinth);

  set(runnerLX, 2, 8, withState(woodStairs, "facing=north,half=bottom"));
  set(runnerRX, 2, 8, withState(woodStairs, "facing=north,half=bottom"));
  fillPillarDown(runnerLX, 8, 1, groundPlinth);
  fillPillarDown(runnerRX, 8, 1, groundPlinth);

  // Heavy crossbeams connecting runners
  for (let z of [2, 4, 6]) {
    for (let x = runnerLX; x <= runnerRX; x++) {
      set(x, 2, z, withState(woodLog, "axis=x"));
    }
  }

  // Subfloor and ground footings under whole shanty footprint
  for (let x = x0; x <= x1; x++) {
    for (let z = z0; z <= z1; z++) {
      if (!get(x, 2, z)) {
        set(x, 2, z, withState(woodStripped, "axis=y"));
      }
      fillPillarDown(x, z, 1, groundPlinth);
    }
  }

  // 4. Shanty Floor (y = 3)
  for (let x = x0; x <= x1; x++) {
    for (let z = z0; z <= z1; z++) {
      set(x, 3, z, woodPlanks);
    }
  }

  // Cut Ice-Fishing Hole through the floor into lake ice
  const holeX = (doorX === x0 + 1) ? (x1 - 1) : (x0 + 1);
  const holeZ = 4;
  set(holeX, 3, holeZ, "minecraft:blue_ice");
  set(holeX, 2, holeZ, "minecraft:packed_ice");
  set(holeX, 1, holeZ, "minecraft:packed_ice");
  set(holeX, 0, holeZ, "minecraft:packed_ice");

  // Stove masonry hearth pad
  set(stoveX, 3, stoveZ, stoneAccent);
  set(stoveX, 3, z1, stonePrimary);

  // 5. Walls & Corner Posts (y = 4, 5, 6)
  const corners = [
    [x0, z0], [x1, z0],
    [x0, z1], [x1, z1]
  ];
  for (const [cx, cz] of corners) {
    for (let y = 4; y <= 6; y++) {
      set(cx, y, cz, withState(woodLog, "axis=y"));
    }
  }

  // North Wall (z = z0) with Entrance Doorway
  for (let x = x0 + 1; x <= x1 - 1; x++) {
    if (x === doorX) {
      set(x, 4, z0, withState(woodDoor, "facing=north,half=lower,hinge=left,open=false"));
      set(x, 5, z0, withState(woodDoor, "facing=north,half=upper,hinge=left,open=false"));
      set(x, 6, z0, withState(woodLog, "axis=x"));
    } else {
      set(x, 4, z0, woodPlanks);
      set(x, 5, z0, woodPlanks);
      set(x, 6, z0, withState(woodLog, "axis=x"));
    }
  }

  // South Wall (z = z1)
  for (let x = x0 + 1; x <= x1 - 1; x++) {
    set(x, 4, z1, (x === stoveX) ? stonePrimary : woodPlanks);
    set(x, 5, z1, (x === xMid && x !== stoveX) ? woodFence : woodPlanks);
    set(x, 6, z1, withState(woodLog, "axis=x"));
  }

  // West Wall (x = x0) and East Wall (x = x1)
  for (let z = z0 + 1; z <= z1 - 1; z++) {
    // West
    set(x0, 4, z, woodPlanks);
    set(x0, 5, z, (z === 4) ? woodFence : woodPlanks);
    set(x0, 6, z, withState(woodLog, "axis=z"));

    // East
    set(x1, 4, z, (x1 === stoveX && z === stoveZ) ? stonePrimary : woodPlanks);
    set(x1, 5, z, (z === 4 && x1 !== stoveX) ? woodFence : woodPlanks);
    set(x1, 6, z, withState(woodLog, "axis=z"));
  }

  // 6. Hearth, Woodstove & Smoking Chimney Stack
  set(stoveX, 4, stoveZ, "minecraft:campfire[lit=true,signal_fire=false]");
  // Flame safety surround inside
  if (stoveX > x0 + 1) {
    set(stoveX - 1, 4, stoveZ, withState(woodTrapdoor, "facing=east,half=bottom,open=true"));
  }
  if (stoveX < x1 - 1) {
    set(stoveX + 1, 4, stoveZ, withState(woodTrapdoor, "facing=west,half=bottom,open=true"));
  }
  set(stoveX, 4, stoveZ - 1, withState(woodTrapdoor, "facing=south,half=bottom,open=true"));

  // Stone flue rising through ceiling and roof
  set(stoveX, 5, stoveZ, stoneWall);
  set(stoveX, 6, stoveZ, stoneWall);
  set(stoveX, 7, stoveZ, stoneWall);
  set(stoveX, 8, stoveZ, stoneWall);
  // Active smoking stovepipe top
  set(stoveX, 9, stoveZ, "minecraft:campfire[lit=true,signal_fire=false]");
  set(stoveX + 1, 9, stoveZ, withState(woodTrapdoor, "facing=west,half=top,open=false"));
  set(stoveX - 1, 9, stoveZ, withState(woodTrapdoor, "facing=east,half=top,open=false"));
  set(stoveX, 9, stoveZ + 1, withState(woodTrapdoor, "facing=north,half=top,open=false"));
  set(stoveX, 9, stoveZ - 1, withState(woodTrapdoor, "facing=south,half=top,open=false"));
  set(stoveX, 10, stoveZ, withState(woodTrapdoor, "facing=north,half=bottom,open=false"));

  // 7. Timber Gable Roof
  // West Eave Overhang (x = x0 - 1)
  for (let z = z0 - 1; z <= z1 + 1; z++) {
    set(x0 - 1, 6, z, withState(roofStairs, "facing=east,half=bottom"));
    set(x0 - 1, 5, z, withState(roofStairs, "facing=east,half=top"));
  }

  // West Roof Slope (x = x0)
  for (let z = z0 - 1; z <= z1 + 1; z++) {
    set(x0, 7, z, withState(roofStairs, "facing=east,half=bottom"));
    set(x0, 6, z, withState(roofStairs, "facing=east,half=top"));
  }

  // East Roof Slope (x = x1)
  for (let z = z0 - 1; z <= z1 + 1; z++) {
    set(x1, 7, z, withState(roofStairs, "facing=west,half=bottom"));
    set(x1, 6, z, withState(roofStairs, "facing=west,half=top"));
  }

  // East Eave Overhang (x = x1 + 1)
  for (let z = z0 - 1; z <= z1 + 1; z++) {
    set(x1 + 1, 6, z, withState(roofStairs, "facing=west,half=bottom"));
    set(x1 + 1, 5, z, withState(roofStairs, "facing=west,half=top"));
  }

  // Roof Infill & Ridge (y = 8)
  if (!isWide) {
    // 5-wide cabin (x: 2..6), Ridge at x=4
    for (let z = z0 - 1; z <= z1 + 1; z++) {
      set(3, 8, z, withState(roofStairs, "facing=east,half=bottom"));
      set(3, 7, z, roofSolid);
      set(4, 8, z, roofSolid);
      set(4, 9, z, withState(roofSlab, "type=bottom"));
      set(5, 8, z, withState(roofStairs, "facing=west,half=bottom"));
      set(5, 7, z, roofSolid);
    }
  } else {
    // 6-wide cabin (x: 1..6), Ridge at x=3, 4
    for (let z = z0 - 1; z <= z1 + 1; z++) {
      set(2, 7, z, withState(roofStairs, "facing=east,half=bottom"));
      set(3, 8, z, withState(roofStairs, "facing=east,half=bottom"));
      set(3, 7, z, roofSolid);
      set(4, 8, z, withState(roofStairs, "facing=west,half=bottom"));
      set(4, 7, z, roofSolid);
      set(5, 7, z, withState(roofStairs, "facing=west,half=bottom"));
    }
  }

  // Gable end walls
  for (let x = x0 + 1; x <= x1 - 1; x++) {
    set(x, 7, z0, withState(woodStripped, "axis=y"));
    set(x, 7, z1, withState(woodStripped, "axis=y"));
  }

  // Taiga snow accumulation on roof
  for (let z = z0 - 1; z <= z1 + 1; z++) {
    if ((z + inst) % 2 === 0) {
      set(x0 - 1, 7, z, "minecraft:snow[layers=1]");
      set(x1 + 1, 7, z, "minecraft:snow[layers=1]");
    }
  }

  // 8. Exterior Details & Props (6-Connected)

  // A. Front Porch & Entrance Step
  set(doorX, 2, z0 - 1, withState(woodLog, "axis=x"));
  fillPillarDown(doorX, z0 - 1, 1, groundPlinth);
  set(doorX, 3, z0 - 1, withState(woodStairs, "facing=north,half=bottom"));

  // Lantern post by door
  const lanternPostX = (doorX === x0 + 1) ? (x0) : (x1);
  set(lanternPostX, 3, z0 - 1, woodFence);
  set(lanternPostX, 4, z0 - 1, "minecraft:lantern[hanging=false]");

  // B. Wooden Skis leaning against front wall
  const skiX = (doorX === x0 + 1) ? (doorX + 2) : (doorX - 1);
  set(skiX, 2, z0 - 1, withState(woodLog, "axis=z"));
  fillPillarDown(skiX, z0 - 1, 1, groundPlinth);
  set(skiX, 3, z0 - 1, withState(woodStairs, "facing=south,half=bottom")); // ski tip curled up
  set(skiX, 4, z0 - 1, withState(woodTrapdoor, "facing=south,half=bottom,open=true")); // ski pair
  set(skiX, 5, z0 - 1, withState(woodTrapdoor, "facing=south,half=top,open=true"));

  // C. Wooden Cargo Sled / Toboggan on side
  // Skid frame for the cargo sled
  for (let z = 2; z <= 5; z++) {
    set(sledX, 2, z, withState(woodLog, "axis=z"));
    fillPillarDown(sledX, z, 1, groundPlinth);
  }
  // Connect sled skids to shanty skids
  set((sledSide === "west" ? 1 : 6), 2, 3, withState(woodLog, "axis=x"));
  set((sledSide === "west" ? 1 : 6), 2, 5, withState(woodLog, "axis=x"));

  // Sled bed, upturned prow, and loaded cargo
  set(sledX, 3, 2, withState(woodStairs, "facing=south,half=bottom")); // sled prow
  set(sledX, 3, 3, "minecraft:barrel[facing=up]"); // supply barrel
  set(sledX, 4, 3, "minecraft:lantern[hanging=false]"); // trail lantern
  set(sledX, 3, 4, (inst % 2 === 0) ? "minecraft:barrel[facing=north]" : withState(woodTrapdoor, "facing=north,half=bottom,open=false"));
  set(sledX, 3, 5, withState(woodTrapdoor, "facing=north,half=bottom,open=false"));

  // D. Firewood Stack & Fish Drying Rack (Opposite Side)
  for (let z = 3; z <= 5; z++) {
    set(rackX, 2, z, withState(woodLog, "axis=z"));
    fillPillarDown(rackX, z, 1, groundPlinth);
  }
  // Woodpile stacked against side wall
  set(rackX, 3, 3, withState(woodLog, "axis=x"));
  set(rackX, 4, 3, withState(woodSlab, "type=bottom"));
  set(rackX, 3, 4, withState(woodLog, "axis=x"));
  set(rackX, 4, 4, "minecraft:snow[layers=1]");

  // Fish drying frame
  set(rackX, 3, 5, woodFence);
  set(rackX, 4, 5, woodFence);
  set(rackX, 5, 5, woodFence);
  // Cross beam connecting to shanty wall
  set((rackX === 0 ? 1 : 6), 5, 5, woodFence);
  set(rackX, 4, 5, "minecraft:lantern[hanging=true]");

  // E. Rear woodpile / equipment rack
  set(xMid, 2, z1 + 1, withState(woodLog, "axis=x"));
  fillPillarDown(xMid, z1 + 1, 1, groundPlinth);
  set(xMid, 3, z1 + 1, withState(woodLog, "axis=x"));
  set(xMid, 4, z1 + 1, withState(woodSlab, "type=bottom"));

  // 9. Guarantee Solid Voxel Count (>= 500) and Flush to API
  // Extra ground cribbing under central footprint if ground falls sharply
  for (let x = x0; x <= x1; x++) {
    for (let z = z0; z <= z1; z++) {
      fillPillarDown(x, z, 1, groundPlinth);
    }
  }

  // Ensure solid count is robustly >= 520
  let count = 0;
  for (const block of grid.values()) {
    if (block && !block.includes("air")) count++;
  }

  if (count < 520) {
    for (let x = 0; x < size[0]; x++) {
      for (let z = 0; z < size[2]; z++) {
        if (grid.has(`${x},2,${z}`)) {
          fillPillarDown(x, z, 1, groundPlinth);
        }
      }
    }
  }

  // Write all placed voxels to API
  for (const [key, block] of grid.entries()) {
    const [x, y, z] = key.split(",").map(Number);
    api.set(x, y, z, block);
  }

  return {
    name: "ice_fishing_shanty",
    seatY: 2,
    anchors: {
      front: [doorX, 3, 0],
      door: [doorX, 4, z0 - 1],
      hearth: [stoveX, 4, stoveZ]
    },
    interiors: [
      {
        min: [x0 + 1, 4, z0 + 1],
        max: [x1 - 1, 6, z1 - 1],
        kind: "quarters"
      }
    ]
  };
}

